root="/Users/jearly/Documents/OceanKitRepositories/wvm-v4-cpp-adoption-audit";
addpath(fullfile(root,"tools"));
configureCIEnvironment(root,"/Users/jearly/Documents/OceanKitRepositories/OceanKit",documentationPackageSpecifier="ClassDocumentation@1.3.2");
cd(root);
addpath(fullfile(root,"UnitTests"),"-begin");
setenv('WV_FORWARD_INTEGRATION_RUNNER','/private/tmp/wvm-v4-audit-runtime/wave-vortex-run');
setenv('WV_FORWARD_INTEGRATION_PROBE','/private/tmp/wvm-v4-audit-runtime/WVForwardIntegrationProbe');
setenv('WV_FORWARD_INTEGRATION_EVIDENCE','/private/tmp/wvm391-density-output-forward-refresh-evidence');
setenv('WV_FORWARD_INTEGRATION_SOURCE_ROOT','/Users/jearly/Documents/OceanKitRepositories/wvm-v4-cpp-adoption-audit');
setenv('WV_STABLE_FORCING_NATIVE','1');
suite=testsuite(fullfile(root,"UnitTests","TestPortableForwardIntegration.m"));
assert(numel(suite)==6);
results=run(suite);
disp(table(results));
file=fopen('/private/tmp/wvm391-density-output-forward-refresh-results.json','w');
fwrite(file,jsonencode(struct(name={results.Name},passed={results.Passed},failed={results.Failed},incomplete={results.Incomplete},duration={results.Duration}),PrettyPrint=true));
fclose(file);
assertSuccess(results);
